import * as React from "react"
import { addPropertyControls, ControlType, RenderTarget } from "framer"

type LoadBridge = { isLoading: boolean; isComplete: boolean; progress?: number; setLoading?: (task?: string) => void; setProgress?: (taskOrProgress: string | number, progress?: number) => void; setComplete?: (task?: string) => void }
type LoadingWindow = Window & { __modelLoadingState?: LoadBridge; __preloadModel3D?: (url: string) => Promise<unknown>; __botanikaLoadingBoot?: { handoff: () => void; startedAt?: number }; __botanika3DReady?: Set<string> }
interface Props { logo?: string; model?: string; waitFor3D?: boolean; images?: string; accent?: string; background?: string; preview?: boolean; audience?: string; onComplete?: () => void; style?: React.CSSProperties }
const LOGO = "https://framerusercontent.com/images/WFpkEY4U2YfWmnJcO1hZ86XpVUQ.png"
const MODEL = "https://framerusercontent.com/assets/exkVGmXjcJJ49fgrMEM9l8NhEM.glb"
const LIGHT_PAGES = new Set(["/contact", "/research", "/bonsai"])
const IMAGES = ["https://framerusercontent.com/images/Hsh1gzdW7jeebdedw9uK0tlm8.png", "https://framerusercontent.com/images/EgH7gkf5tEj7PqdWjEfAstT8h4Q.png", "https://framerusercontent.com/images/SISGSkjCPtmS6V2h8aWOgR922DM.png", "https://framerusercontent.com/images/a3i1ToBatXHw86retpZP4HbO72c.png"]

/**
 * @framerIntrinsicWidth 390
 * @framerIntrinsicHeight 844
 * @framerSupportedLayoutWidth any-prefer-fixed
 * @framerSupportedLayoutHeight any-prefer-fixed
 */
export default function BotanikaLoading({ logo = LOGO, model = MODEL, waitFor3D = false, images = IMAGES.join("\n"), accent = "#FE7426", background = "#000000", preview = false, audience = "Desktop", onComplete, style }: Props) {
    const canvas = RenderTarget.current() === RenderTarget.canvas
    const dialog = React.useRef<HTMLDialogElement>(null)
    const logoStage = React.useRef<HTMLDivElement>(null)
    const [progress, setProgress] = React.useState(0)
    const [phase, setPhase] = React.useState("Loading assets")
    const [error, setError] = React.useState(false)
    const [leaving, setLeaving] = React.useState(false)
    const [done, setDone] = React.useState(false)
    const [attempt, setAttempt] = React.useState(0)
    const retry = () => { setDone(false); setLeaving(false); setError(false); setProgress(0); setAttempt(n => n + 1) }
    const finishLoading = () => {
        dialog.current?.close()
        // Dialog.close restores focus to the page scroller in Framer/Chromium.
        // Clear that structural focus ring without blurring an interactive control.
        const active = document.activeElement
        if (active instanceof HTMLElement && !active.matches("a[href],button,input,textarea,select,[contenteditable=true],[role=button],[role=link]")) active.blur()
        setDone(true)
    }
    const completionNotified = React.useRef(false)
    React.useEffect(() => {
        if (!done) { completionNotified.current = false; return }
        if (completionNotified.current) return
        completionNotified.current = true
        onComplete?.()
    }, [done, onComplete])

    React.useEffect(() => {
        if (canvas || preview || done || typeof window === "undefined") return
        if ((window.innerWidth < 1200) !== (audience === "Phone")) return
        const path = window.location.pathname.replace(/\/+$/, "") || "/"
        if (LIGHT_PAGES.has(path) || !waitFor3D) {
            (window as LoadingWindow).__botanikaLoadingBoot?.handoff()
            dialog.current?.close()
            setDone(true)
            return
        }
        let cancelled = false, closing = false, completionScheduled = false, modelReady = false, modelProgress = 0, parsed = false, documentReady = false, fontsReady = false, imagesDone = 0
        const scrollStyles = { html: document.documentElement.style.overflow, body: document.body.style.overflow, overscroll: document.documentElement.style.overscrollBehavior }
        document.documentElement.style.overflow = "hidden"
        document.body.style.overflow = "hidden"
        document.documentElement.style.overscrollBehavior = "none"
        const win = window as LoadingWindow
        const loadingStartedAt = performance.now()
        const introStartedAt = win.__botanikaLoadingBoot?.startedAt ?? loadingStartedAt
        logoStage.current?.style.setProperty("--botanika-logo-delay", `${-Math.max(0, loadingStartedAt - introStartedAt)}ms`)
        const timers = new Set<number>()
        const frames = new Set<number>()
        const pendingImages: HTMLImageElement[] = []
        const sources = Array.from(new Set([logo, ...images.split(/\n|,/).map(s => s.trim()).filter(Boolean)]))
        const delay = (fn: () => void, ms: number) => { const id = window.setTimeout(() => { timers.delete(id); if (!cancelled) fn() }, ms); timers.add(id); return id }
        const frame = (fn: () => void) => { const id = requestAnimationFrame(() => { frames.delete(id); if (!cancelled) fn() }); frames.add(id) }
        const stopScroll = (event: Event) => { if (event.cancelable) event.preventDefault() }
        const close = () => {
            if (closing || cancelled) return
            closing = true
            setLeaving(true)
            delay(finishLoading, window.matchMedia("(prefers-reduced-motion: reduce)").matches ? 0 : 1400)
        }
        const update = () => {
            if (cancelled || closing) return
            const value = (documentReady ? 5 : 0) + (fontsReady ? 5 : 0) + (waitFor3D ? 20 : 90) * imagesDone / Math.max(1, sources.length) + (waitFor3D ? modelReady ? 70 : Math.min(66, 66 * modelProgress / .95) : 0)
            setProgress(old => Math.max(old, Math.min(99, Math.floor(value))))
            setPhase(!documentReady || !fontsReady || imagesDone < sources.length ? "Loading assets" : modelReady ? "Ready" : parsed ? "Preparing 3D scene" : "Loading NIMBUS")
            if (documentReady && fontsReady && imagesDone === sources.length && modelReady) {
                setError(false)
                setProgress(100); setPhase("Ready")
                if (!completionScheduled) { completionScheduled = true; delay(close, Math.max(500, 1850 - (performance.now() - introStartedAt))) }
            }
        }
        const fail = () => { if (!cancelled && !closing && !completionScheduled) { setError(true); setPhase("Loading is taking longer than expected") } }
        try {
            const panel = dialog.current
            if (panel?.open) panel.close()
            panel?.showModal()
            // The early HTML loader stays visible until this modal has taken over
            if (panel?.open) win.__botanikaLoadingBoot?.handoff()
        } catch { fail() }
        window.addEventListener("wheel", stopScroll, { passive: false })
        window.addEventListener("touchmove", stopScroll, { passive: false })
        const previous = win.__modelLoadingState
        const initialComplete = win.__botanika3DReady?.has(model) === true || previous?.isComplete === true
        modelProgress = typeof previous?.progress === "number" && Number.isFinite(previous.progress) ? Math.max(0, Math.min(1, previous.progress)) : 0
        parsed = modelProgress >= .95
        const forward = (method: "setLoading" | "setProgress" | "setComplete", ...args: unknown[]) => {
            try { (previous?.[method] as ((...values: unknown[]) => void) | undefined)?.apply(previous, args) } catch { /* Old observers may already be detached after navigation. */ }
        }
        const bridge: LoadBridge = {
            isLoading: !initialComplete, isComplete: initialComplete, progress: initialComplete ? 1 : modelProgress,
            setLoading: task => { bridge.isLoading = true; forward("setLoading", task) },
            setProgress: (taskOrProgress, progress) => {
                const n = typeof taskOrProgress === "number" ? taskOrProgress : progress
                if (typeof n === "number" && Number.isFinite(n) && (typeof taskOrProgress === "number" || taskOrProgress === model)) {
                    modelProgress = Math.max(0, Math.min(1, n)); bridge.progress = modelProgress
                    if (modelProgress >= .95) parsed = true
                }
                forward("setProgress", taskOrProgress, progress); update()
            },
            setComplete: task => { bridge.isComplete = true; bridge.isLoading = false; bridge.progress = 1; modelProgress = 1; modelReady = true; parsed = true; forward("setComplete", task); update() },
        }
        if (waitFor3D) win.__modelLoadingState = bridge
        modelReady = !waitFor3D || initialComplete
        const onLoad = () => { documentReady = true; update() }
        if (document.readyState === "complete") documentReady = true
        else window.addEventListener("load", onLoad, { once: true })
        Promise.resolve(document.fonts?.ready).then(() => { if (!cancelled) { fontsReady = true; update() } }, fail)
        for (const src of sources) {
            const image = new Image()
            pendingImages.push(image)
            image.onload = () => { Promise.resolve(image.decode?.()).catch(() => {}).then(() => { if (!cancelled) { imagesDone++; update() } }) }
            image.onerror = fail
            image.src = src
        }
        // Only pages configured with a 3D scene preload a model and wait for renderer completion.
        let bridgeAttempts = 0
        const preload = () => {
            if (cancelled || modelReady) { update(); return }
            if (typeof win.__preloadModel3D !== "function") {
                if (++bridgeAttempts < 100) delay(preload, 100)
                else fail()
                return
            }
            Promise.resolve(win.__preloadModel3D(model)).then(() => {
                if (cancelled) return
                parsed = true
                modelProgress = Math.max(modelProgress, .95)
                if (bridge.isComplete || win.__modelLoadingState?.isComplete) modelReady = true
                update()
            }, fail)
        }
        const onSceneReady = (event: Event) => {
            if ((event as CustomEvent<{url: string}>).detail?.url !== model) return
            modelReady = true; parsed = true; modelProgress = 1; update()
        }
        if (waitFor3D) window.addEventListener("botanika:3d-ready", onSceneReady)
        const checkRenderer = () => {
            if (cancelled || closing || modelReady) return
            const current = win.__modelLoadingState
            if (win.__botanika3DReady?.has(model) || current?.isComplete || current?.progress === 1) {
                modelReady = true; parsed = true; modelProgress = 1; update()
            } else delay(checkRenderer, 100)
        }
        if (waitFor3D) { frame(() => frame(preload)); delay(checkRenderer, 100) }
        delay(fail, 20000)
        update()
        return () => {
            cancelled = true
            document.documentElement.style.overflow = scrollStyles.html
            document.body.style.overflow = scrollStyles.body
            document.documentElement.style.overscrollBehavior = scrollStyles.overscroll
            timers.forEach(id => clearTimeout(id)); frames.forEach(id => cancelAnimationFrame(id))
            pendingImages.forEach(image => { image.onload = null; image.onerror = null })
            window.removeEventListener("botanika:3d-ready", onSceneReady)
            window.removeEventListener("load", onLoad)
            window.removeEventListener("wheel", stopScroll)
            window.removeEventListener("touchmove", stopScroll)
            dialog.current?.close()
            // Keep the bridge completion flags available for cached revisits; detach React callbacks.
            if (waitFor3D && win.__modelLoadingState === bridge) win.__modelLoadingState = { isLoading: bridge.isLoading, isComplete: bridge.isComplete, progress: bridge.progress,
                setLoading() { this.isLoading = true }, setProgress(taskOrProgress, progress) { const n = typeof taskOrProgress === "number" ? taskOrProgress : progress; if (typeof n === "number" && Number.isFinite(n)) this.progress = n }, setComplete() { this.isComplete = true; this.isLoading = false; this.progress = 1 } }
        }
    }, [canvas, preview, done, attempt, logo, model, waitFor3D, images, audience])

    const displayProgress = preview ? 64 : progress
    const digits = String(displayProgress)
    const content = <div data-loader-state={leaving ? "revealing" : "loading"} style={{ position: "relative", width: "100%", height: "100%", overflow:"hidden", background:"transparent", color: "#FFFFFF", boxSizing: "border-box", fontFamily: '\"Plus Jakarta Sans\", Inter, sans-serif' }}>
        <style>{`
            @keyframes botanika-loader-appear { from {-webkit-mask-position:100% 0;mask-position:100% 0;} to {-webkit-mask-position:0% 0;mask-position:0% 0;} }
            .botanika-loader-logo { -webkit-mask-image:linear-gradient(90deg,#000 0%,#000 46%,transparent 54%,transparent 100%);mask-image:linear-gradient(90deg,#000 0%,#000 46%,transparent 54%,transparent 100%);-webkit-mask-size:250% 100%;mask-size:250% 100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;-webkit-mask-position:100% 0;mask-position:100% 0;animation:botanika-loader-appear 1600ms cubic-bezier(.4,0,.2,1) both;animation-delay:var(--botanika-logo-delay,0ms);will-change:mask-position; }
            .botanika-loading-dialog::backdrop { background:transparent; }
            .botanika-loader-action:focus-visible { outline:1px solid white; outline-offset:5px; }
            @media(prefers-reduced-motion:reduce) { .botanika-loader-logo {animation:none!important;-webkit-mask-image:none!important;mask-image:none!important} .botanika-loader-digit,.botanika-loader-curtain {transition:none!important} }
        `}</style>
        <div aria-hidden="true" className="botanika-loader-curtain" style={{position:"absolute",left:0,right:0,top:0,height:"calc(50% + 1px)",background,transform:leaving?"translate3d(0,-101%,0)":"translate3d(0,0,0)",transition:"transform 1350ms cubic-bezier(.76,0,.24,1)",willChange:"transform"}} />
        <div aria-hidden="true" className="botanika-loader-curtain" style={{position:"absolute",left:0,right:0,bottom:0,height:"calc(50% + 1px)",background,transform:leaving?"translate3d(0,101%,0)":"translate3d(0,0,0)",transition:"transform 1350ms cubic-bezier(.76,0,.24,1)",willChange:"transform"}} />
        <div ref={logoStage} className="botanika-loader-logo" style={{position:"absolute",left:"50%",top:"50%",width:"min(440px,72vw)",transform:"translate(-50%,-50%)",pointerEvents:"none",WebkitMaskImage:leaving?"none":undefined,maskImage:leaving?"none":undefined}}>
            <img src={logo} loading="eager" fetchPriority="high" alt="Botanika" width={440} height={87} style={{display:"block",width:"100%",height:"auto",objectFit:"contain",filter:"brightness(0) invert(1)",opacity:leaving?0:1,transform:leaving?"translateY(-24px) scale(.94)":"translateY(0) scale(1)",transition:"transform 1350ms cubic-bezier(.76,0,.24,1),opacity 1350ms cubic-bezier(.76,0,.24,1)"}} />
        </div>
        <div role="progressbar" aria-label="Loading Botanika" aria-valuemin={0} aria-valuemax={100} aria-valuenow={displayProgress} aria-valuetext={`${displayProgress}%`} style={{position:"absolute",left:"50%",top:"calc(50% + clamp(42px,5.3vw,72px))",transform:"translateX(-50%)",display:"flex",alignItems:"baseline",fontFamily:'"DM Mono", "Courier New", monospace',fontSize:12,fontWeight:400,lineHeight:1.2,letterSpacing:".04em",fontVariantNumeric:"tabular-nums",opacity:leaving?0:1,transition:"opacity 1350ms cubic-bezier(.76,0,.24,1)"}}>
            <span aria-hidden="true" style={{display:"flex"}}>{Array.from(digits).map((digit,index)=><span key={digits.length-index} style={{display:"inline-block",width:"1ch",height:"1.2em",overflow:"hidden"}}><span className="botanika-loader-digit" style={{display:"block",transform:`translateY(-${Number(digit)*1.2}em)`,transition:"transform 380ms cubic-bezier(.22,1,.36,1)"}}>{Array.from({length:10},(_,n)=><span key={n} style={{display:"block",height:"1.2em",lineHeight:"1.2em"}}>{n}</span>)}</span></span>)}</span>
            <span aria-hidden="true" style={{marginLeft:2}}>%</span>
        </div>
        {error && <div style={{position:"absolute",left:"50%",top:"calc(50% + 116px)",transform:"translateX(-50%)",width:"min(360px,calc(100% - 48px))",textAlign:"center"}}>
            <p role="status" style={{margin:"0 0 18px",fontSize:12,lineHeight:1.6,color:"#9c9c9c"}}>Loading is taking longer than expected. Retry or continue to the site.</p>
            <div style={{display:"flex",justifyContent:"center",gap:24}}>
                <button className="botanika-loader-action" onClick={retry} style={{border:"1px solid #3a3a3a",background:"transparent",color:"#fff",padding:"10px 18px",fontFamily:"inherit",fontSize:11,letterSpacing:".08em",textTransform:"uppercase",cursor:"pointer"}}>Retry</button>
                <button className="botanika-loader-action" onClick={finishLoading} style={{border:0,background:"transparent",color:"#aaa",fontFamily:"inherit",fontSize:11,letterSpacing:".08em",textTransform:"uppercase",cursor:"pointer"}}>Continue to site</button>
            </div>
        </div>}
    </div>
    if (canvas && !preview || done) return <div style={{ ...style, position: "relative", pointerEvents: "none" }} />
    if (preview) return <div style={{ ...style, position: "relative", width: "100%", height: "100%" }}>{content}</div>
    return <div style={{ ...style, position: "relative", pointerEvents: "none" }}><dialog ref={dialog} className="botanika-loading-dialog" aria-label="Loading Botanika" onCancel={event => event.preventDefault()} style={{ position: "fixed", inset: 0, margin: 0, padding: 0, width: "100vw", height: "100dvh", maxWidth: "none", maxHeight: "none", border: 0, outline: "none", boxShadow: "none", overflow: "hidden", background:"transparent", pointerEvents: "auto", zIndex: 2147483647 }}>{content}</dialog></div>
}
addPropertyControls(BotanikaLoading, {
    onComplete: { type: ControlType.EventHandler, title: "Loading complete" },
    logo: { type: ControlType.File, title: "Logo", allowedFileTypes: ["png", "svg", "webp"] },
    waitFor3D: { type: ControlType.Boolean, title: "Wait for 3D", defaultValue: false },
    model: { type: ControlType.File, title: "Model", allowedFileTypes: ["glb", "gltf"], hidden: props => !props.waitFor3D },
    images: { type: ControlType.String, title: "Assets", displayTextArea: true, defaultValue: IMAGES.join("\n") },
    accent: { type: ControlType.Color, title: "Accent", defaultValue: "#FE7426" },
    background: { type: ControlType.Color, title: "Background", defaultValue: "#000000" },
    audience: { type: ControlType.Enum, title: "Breakpoint", options: ["Desktop", "Phone"], defaultValue: "Desktop" },
    preview: { type: ControlType.Boolean, title: "Design Preview", defaultValue: false },
})
